document.querySelectorAll('[data-contact-form]').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;const field=name=>form.querySelector('[name="'+name+'"]')?.value.trim()||'';const body='Hello Jamiu,\n\n'+field('field')+'\n\nName: '+field('full-Name')+'\nEmail: '+field('email-address')+(field('phone-number')?'\nPhone: '+field('phone-number'):'');const href='mailto:aabdulfataijamiu@gmail.com?subject='+encodeURIComponent(field('subject')||'Product design enquiry')+'&body='+encodeURIComponent(body);let status=form.querySelector('.form-status');if(!status){status=document.createElement('p');status.className='form-status';form.append(status)}status.replaceChildren('Your email draft is ready. ');const link=document.createElement('a');link.href=href;link.textContent='Open your email app to review and send ↗';status.append(link);link.focus()}));
